if (this.protocol === "application/pgp-signature") {
  if (!this.mimeSignatureData) {
    this.exitCode = -1;
    this.returnStatus = new lazy.DecryptVerifyResult();
    this.returnStatus.statusFlags = EnigmailConstants.BAD_SIGNATURE;
    this.returnStatus.errorMsg = "Signature data missing";
    this.displayStatus(mimeSvc.mailChannel?.openpgpSink);
    return;
  }

result.exitCode = RNPLib.rnp_op_verify_execute(verify_op);

const haveSignature = await this.getVerifyDetails(
  RNPLib.ffi,
  fromAddr,
  msgDate,
  verify_op,
  result
);
if (!haveSignature) {
  if (!result.exitCode) {
    /* Don't allow a good exit code. Keep existing bad code. */
    result.exitCode = -1;
  }
  result.statusFlags |= lazy.EnigmailConstants.BAD_SIGNATURE;
}

displayStatus(sink) {
  if (this.exitCode === null || this.statusDisplayed || this.backgroundJob) {
    return;
  }

  if (!sink) {
    return;
  }
